    address public victim = makeAddr("victim");
    uint256 public wagerLimit = 1 ether;
    uint256 public initialTokenBalance = 1000 ether;

    function setUp() public {
        vm.prank(owner);
        game = new PoCGame(whale, wagerLimit);

